const std = @import("std");

const Node = struct {
    value: i32,
    left: ?*Node,
    right: ?*Node,
};

fn serialize(node: ?*Node, buf: []i32, idx: *usize) void {
    if (node) |n| {
        buf[idx.*] = n.value;
        idx.* += 1;
        serialize(n.left, buf, idx);
        serialize(n.right, buf, idx);
    } else {
        buf[idx.*] = -1;
        idx.* += 1;
    }
}

pub fn main() !void {
    var n3 = Node{ .value = 3, .left = null, .right = null };
    var n2 = Node{ .value = 2, .left = null, .right = null };
    var n1 = Node{ .value = 1, .left = &n2, .right = &n3 };

    var buf: [7]i32 = undefined;
    var idx: usize = 0;
    serialize(&n1, &buf, &idx);

    for (0..idx) |i| std.debug.print("{} ", .{buf[i]});
    std.debug.print("\n", .{});
}
